import { createHash } from "node:crypto";
import { expect, it } from "vitest";
import gameReference from "./fixtures/python-reference.json?raw";
import trainerReference from "./fixtures/python-trainer-reference.json?raw";

// Frozen independent evidence from the retired Python implementation, not
// snapshots generated by the implementation under test. See fixtures/README.md.
it.each([
  [
    "game/strategy",
    gameReference,
    "7d681873ea10cfd0ae6c891b385e369bd4ddb787ffa0c461d6d0026475ee27c2",
  ],
  [
    "trainer",
    trainerReference,
    "9df577bd224bc7bc7cb640439ae41e1958f34b3ee7a6758619a90831aa2e476a",
  ],
])("preserves the frozen %s baseline", (_name, source, fingerprint) => {
  expect(createHash("sha256").update(source, "utf8").digest("hex")).toBe(
    fingerprint,
  );
});

it("retains the full independent comparison coverage", () => {
  const games = JSON.parse(gameReference) as {
    format: number;
    games: unknown[];
    strategyHands: unknown[];
    strategies: { decisions: string }[];
  };
  const trainer = JSON.parse(trainerReference) as {
    format: number;
    cases: { frames: unknown[] }[];
  };
  expect(games.format).toBe(1);
  expect(trainer.format).toBe(1);
  expect(games.games).toHaveLength(175);
  expect(games.strategies).toHaveLength(64);
  expect(games.strategyHands).toHaveLength(107);
  expect(
    games.strategies.reduce((sum, entry) => sum + entry.decisions.length, 0),
  ).toBe(68_480);
  expect(trainer.cases).toHaveLength(93);
  expect(
    trainer.cases.reduce((sum, entry) => sum + entry.frames.length, 0),
  ).toBe(618);
});
